#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20};
    // Assume capacity is 2
    int* p = &v[0];

    // Request a large capacity, forcing reallocation
    v.reserve(100);

    // DANGER: p points to the old memory location
    // Accessing *p is UNDEFINED BEHAVIOR
    // if reallocation actually occurred (which it usually does here).
    // std::cout << *p << std::endl; 

    // Safe access requires re-obtaining the pointer:
    std::cout << v[0] << std::endl; // Output: 10
}
